CREATE TABLE public.shirt_campaign_lots (id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, campaign_id UUID NOT NULL REFERENCES public.shirt_campaigns(id) ON DELETE CASCADE, quantity INTEGER NOT NULL, unit_cost NUMERIC(12,2) NOT NULL DEFAULT 0, total_cost NUMERIC(12,2) NOT NULL DEFAULT 0, supplier TEXT, purchase_date DATE NOT NULL DEFAULT CURRENT_DATE, notes TEXT, transaction_id UUID, society_id UUID NOT NULL, created_by UUID NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.shirt_campaign_lots TO authenticated;
GRANT ALL ON public.shirt_campaign_lots TO service_role;
ALTER TABLE public.shirt_campaign_lots ENABLE ROW LEVEL SECURITY;
CREATE POLICY "lots_select" ON public.shirt_campaign_lots FOR SELECT TO authenticated USING (has_role(auth.uid(), 'admin'::app_role) OR has_role(auth.uid(), 'pastor'::app_role) OR (has_role(auth.uid(), 'diretoria'::app_role) AND society_id = get_user_society_id(auth.uid())));
CREATE POLICY "lots_manage" ON public.shirt_campaign_lots FOR ALL TO authenticated USING (has_role(auth.uid(), 'admin'::app_role) OR (has_role(auth.uid(), 'diretoria'::app_role) AND society_id = get_user_society_id(auth.uid()))) WITH CHECK (has_role(auth.uid(), 'admin'::app_role) OR (has_role(auth.uid(), 'diretoria'::app_role) AND society_id = get_user_society_id(auth.uid())));
CREATE TRIGGER update_shirt_campaign_lots_updated_at BEFORE UPDATE ON public.shirt_campaign_lots FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();